function setMode(type){walking=type==='walk';controls.maxPolarAngle=walking?Math.PI*.85:Math.PI*.49;controls.enablePan=!walking;for(const id of ['orbit','top','walk'])$(id).classList.toggle('active',id===type);$('move').style.display=walking?'block':'none';$('help').textContent=walking?'Passeio livre · arraste para olhar · W A S D ou setas':'Arraste para girar · role para aproximar · botão direito para mover';if(walking){$('low').checked=false;setCut();$('roof').checked=false;roof.visible=false;view([6,1.65,11],[6,1.65,8]);}else if(type==='top'){$('detail').innerHTML='<span class="eyebrow">LEITURA DA PLANTA</span><h2>Medidas e contornos</h2><p>Selecione um piso para consultar as cotas e áreas. Contornos 3D reconstruídos pelas dimensões do PDF.</p><button id="sourceplan">Ver desenho vetorial original ↗</button>';$('sourceplan').onclick=()=>modal('planta-original.svg','Planta cotada · extração vetorial do PDF','Geometria e textos originais da prancha, sem redesenho.');view([5,32,12.51],[5,0,12.5]);$('roof').checked=false;roof.visible=false;}else view([25,24,36],[5,0,12.3]);$('mode').textContent=walking?'Passeio interior':type==='top'?'Planta · contornos dos ambientes':'Térreo · vista aberta';}
