function move(dir){if(!walking)return;const v=controls.target.clone().sub(camera.position);v.y=0;v.normalize();if(dir==='back')v.negate();if(dir==='left')v.applyAxisAngle(new T.Vector3(0,1,0),Math.PI/2);if(dir==='right')v.applyAxisAngle(new T.Vector3(0,1,0),-Math.PI/2);v.multiplyScalar(.28);const next=camera.position.clone().add(v);if(next.x<.2||next.x>9.8||next.z<.2||next.z>25)return;camera.position.add(v);controls.target.add(v);camera.position.y=controls.target.y=1.65;}
